{"command":"cat <<'EOF' > format.go
package main

import "fmt"

func formatSize(size int64, si bool) string {
	if si {
		if size < 1000 {
			return fmt.Sprintf("%d B", size)
		}
		units := []string{"kB", "MB", "GB", "TB", "PB", "EB"}
		val := float64(size)
		base := 1000.0
		for _, unit := range units {
			val /= base
			if val < base {
				return fmt.Sprintf("%.1f %s", val, unit)
			}
		}
		return fmt.Sprintf("%.1f %s", val, units[len(units)-1])
	} else {
		if size < 1024 {
			return fmt.Sprintf("%d B", size)
		}
		units := []string{"KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
		val := float64(size)
		base := 1024.0
		for _, unit := range units {
			val /= base
			if val < base {
				return fmt.Sprintf("%.1f %s", val, unit)
			}
		}
		return fmt.Sprintf("%.1f %s", val, units[len(units)-1])
	}
}

func formatLine(flag string, sizeStr string) string {
    // total prefix length is 12: flag(1) + right_aligned_sizeStr(10) + space(1)
	paddedSize := fmt.Sprintf("%10s", sizeStr)
	return fmt.Sprintf("%s%s ", flag, paddedSize)
}
EOF"}

