{"command":"cat <<'EOF' > structs.go
package main

import "os"

type FileItem struct {
	Name     string
	Path     string
	ASize    int64
	DSize    int64
	MTime    int64
	IsDir    bool
	Ino      uint64
	Dev      uint64
	Nlink    uint64
	IsSymlink bool
	IsHardlink bool
	ErrHere  bool
	ErrSub   bool
	IsEmpty  bool
	Parent   *FileItem
	Children []*FileItem
	NotReg   bool
}

func getDirSize(item *FileItem, apparent bool) int64 {
	var total int64 = 0
	if item.IsDir {
		total += item.DSize
		if apparent {
			total = item.ASize
		}
		for _, child := range item.Children {
			total += getDirSize(child, apparent)
		}
	} else {
		if !item.IsHardlink {
			if apparent {
				total += item.ASize
			} else {
				total += item.DSize
			}
		}
	}
	return total
}
EOF"}

