package main

func calcSize(item *FileItem, apparent bool) int64 {
	var total int64 = 0
	if apparent {
		total += item.ASize
	} else {
		total += item.DSize
	}

	if item.IsDir {
		for _, child := range item.Children {
			total += calcSize(child, apparent)
		}
	} else {
		if item.IsHardlink {
			return 0
		}
	}
	return total
}
