package main

import (
	"sort"
	"strings"
)

type SortBy struct {
	Items    []*FileItem
	Apparent bool
}

func (s SortBy) Len() int      { return len(s.Items) }
func (s SortBy) Swap(i, j int) { s.Items[i], s.Items[j] = s.Items[j], s.Items[i] }
func (s SortBy) Less(i, j int) bool {
	sizeI := calcSize(s.Items[i], s.Apparent)
	sizeJ := calcSize(s.Items[j], s.Apparent)
	if sizeI != sizeJ {
		return sizeI > sizeJ
	}
	return strings.Compare(s.Items[i].Name, s.Items[j].Name) > 0
}

func sortItems(items []*FileItem, apparent bool) {
	sort.Sort(SortBy{Items: items, Apparent: apparent})
}

// For JSON output, files are ASCENDING, dirs are just alphabetical?
// I observed JSON dirs can be random but I'll do ASCENDING for all.
type SortAsc struct {
	Items []*FileItem
}
func (s SortAsc) Len() int      { return len(s.Items) }
func (s SortAsc) Swap(i, j int) { s.Items[i], s.Items[j] = s.Items[j], s.Items[i] }
func (s SortAsc) Less(i, j int) bool {
	return strings.Compare(s.Items[i].Name, s.Items[j].Name) < 0
}
func sortAscending(items []*FileItem) {
	sort.Sort(SortAsc{Items: items})
}
EOF"}

