	if item.IsDir {
		arr := []interface{}{}
		dirObj := JsonDir{
			Name:  item.Name,
			MTime: item.MTime,
		}
		if isRoot {
			dirObj.Name = item.Path
		}
		arr = append(arr, dirObj)

		// Files first
