			}
			if f.IsSymlink || f.NotReg {
				fObj.Notreg = true
			}
			arr = append(arr, fObj)
		}
		for _, d := range dirs {
			arr = append(arr, itemToJson(d, false))
		}
		return arr
	} else {
		return nil
	}
}

