package main

import (
	"encoding/json"
	"os"
	"time"
)

func writeJson(item *FileItem, outPath string) error {
	header := map[string]interface{}{
		"progname":  "gdu",
		"progver":   "dev",
		"timestamp": time.Now().Unix(),
	}

	rootArr := []interface{}{
		1,
		2,
		header,
		dirToArray(item, true),
	}

	b, err := json.Marshal(rootArr)
	if err != nil {
		return err
	}

	return os.WriteFile(outPath, b, 0644)
}

func dirToArray(item *FileItem, isRoot bool) []interface{} {
	arr := []interface{}{}

	dirObj := map[string]interface{}{
		"name":  item.Name,
		"mtime": item.MTime,
	}
	if isRoot {
		dirObj["name"] = item.Path
	}
	arr = append(arr, dirObj)

	files := []*FileItem{}
	dirs := []*FileItem{}
	for _, child := range item.Children {
		if child.IsDir {
			dirs = append(dirs, child)
		} else {
			files = append(files, child)
		}
	}
	sortAscending(files)
	sortAscending(dirs)

	for _, f := range files {
		fObj := map[string]interface{}{
			"name":  f.Name,
			"mtime": f.MTime,
		}
		if f.ASize > 0 || f.DSize > 0 {
			fObj["asize"] = f.ASize
			fObj["dsize"] = f.DSize
		}
		if f.Nlink > 1 && !f.IsDir {
			fObj["ino"] = f.Ino
			fObj["hlnkc"] = true
		}
		if f.IsSymlink || f.NotReg {
			fObj["notreg"] = true
		}
		arr = append(arr, fObj)
	}

	for _, d := range dirs {
		arr = append(arr, dirToArray(d, false))
	}

	return arr
}
EOF"}

