{"command":"cat <<'EOF' > scanner.go
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"syscall"
	"sync"
)

type VisitedMap struct {
	mu sync.Mutex
	m  map[string]bool
}

func scanDir(path string, parent *FileItem, visited *VisitedMap) *FileItem {
	info, err := os.Lstat(path)
	item := &FileItem{
		Name: filepath.Base(path),
		Path: path,
	}
	if path == "/" {
		item.Name = "/"
	}

	if err != nil {
		item.ErrHere = true
		return item
	}

	item.MTime = info.ModTime().Unix()
	item.IsDir = info.IsDir()
	item.IsSymlink = info.Mode()&os.ModeSymlink != 0
	item.NotReg = !info.Mode().IsRegular() && !item.IsDir && !item.IsSymlink

	if stat, ok := info.Sys().(*syscall.Stat_t); ok {
		item.Ino = stat.Ino
		item.Dev = stat.Dev
		item.Nlink = uint64(stat.Nlink)
		item.ASize = stat.Size
		item.DSize = stat.Blocks * 512

		if item.Nlink > 1 && !item.IsDir {
			key := fmt.Sprintf("%d_%d", item.Dev, item.Ino)
			visited.mu.Lock()
			if visited.m[key] {
				item.IsHardlink = true
			} else {
				visited.m[key] = true
			}
			visited.mu.Unlock()
		}
	} else {
		item.ASize = info.Size()
		item.DSize = info.Size()
	}

	if item.IsDir {
		if item.ASize < 4096 {
			item.ASize = 4096
		}
		if item.DSize < 4096 {
			item.DSize = 4096
		}

		f, err := os.Open(path)
		if err != nil {
			item.ErrHere = true
			return item
		}
		names, err := f.Readdirnames(-1)
		f.Close()
		if err != nil {
			item.ErrHere = true
			return item
		}
		if len(names) == 0 {
			item.IsEmpty = true
		}
		for _, name := range names {
			childPath := filepath.Join(path, name)
			child := scanDir(childPath, item, visited)
			item.Children = append(item.Children, child)
			if child.ErrHere || child.ErrSub {
				item.ErrSub = true
			}
		}
	}

	return item
}
EOF
