	MTime int64  `json:"mtime"`
}

type JsonFile struct {
	Name   string `json:"name"`
	ASize  int64  `json:"asize,omitempty"`
	DSize  int64  `json:"dsize,omitempty"`
	MTime  int64  `json:"mtime"`
	Ino    uint64 `json:"ino,omitempty"`
	Hlnkc  bool   `json:"hlnkc,omitempty"`
	Notreg bool   `json:"notreg,omitempty"`
}

func itemToJson(item *FileItem, isRoot bool) interface{} {
	if item.IsDir {
		arr := []interface{}{}
		dirObj := JsonDir{
			Name:  item.Name,
			MTime: item.MTime,
		}
		if isRoot {
			dirObj.Name = item.Path
		}
		arr = append(arr, dirObj)

		files := []*FileItem{}
		dirs := []*FileItem{}
		for _, child := range item.Children {
			if child.IsDir {
				dirs = append(dirs, child)
			} else {
				files = append(files, child)
			}
		}
		sortAscending(files)
		sortAscending(dirs)

		for _, f := range files {
			fObj := JsonFile{
				Name:  f.Name,
				MTime: f.MTime,
			}
			if f.ASize > 0 || f.DSize > 0 {
				fObj.ASize = f.ASize
				fObj.DSize = f.DSize
			}
			if !f.IsDir && f.Nlink > 1 {
				fObj.Ino = f.Ino
				fObj.Hlnkc = true
			}
			if f.IsSymlink || f.NotReg {
				fObj.Notreg = true
			}
			arr = append(arr, fObj)
		}
		for _, d := range dirs {
			arr = append(arr, itemToJson(d, false))
		}
		return arr
	} else {
		return nil
	}
}

func writeJson(item *FileItem, outPath string) error {
	header := JsonHeader{
		Progname:  "gdu",
		Progver:   "dev",
		Timestamp: time.Now().Unix(),
	}

	rootArr := []interface{}{
		1,
		2,
		header,
		itemToJson(item, true),
	}

	b, err := json.Marshal(rootArr)
	if err != nil {
		return err
	}

	return os.WriteFile(outPath, b, 0644)
}
